"""Dependency graph for a pipeline of tasks.

The :class:`Dag` is a directed acyclic graph whose nodes are task identifiers
and whose edges point from a dependency to the task that depends on it -- an
edge ``a -> b`` means "``b`` depends on ``a``", so ``a`` must finish before
``b`` may start.

The class supports the queries the scheduler and reporting layers need:

* :meth:`Dag.topological_levels` -- the graph flattened into ordered "waves"
  of tasks that could run in parallel.
* :meth:`Dag.detect_cycle` / :meth:`Dag.assert_acyclic` -- cycle detection.
* :meth:`Dag.transitive_dependents` -- everything downstream of a node, used to
  cascade skips when a task fails permanently.
* :meth:`Dag.roots` / :meth:`Dag.leaves` -- entry and exit nodes.

All traversals visit neighbours in the deterministic order the nodes and edges
were added, so results are reproducible.
"""

from __future__ import annotations

from taskflow.model import GraphError


class Dag:
    """A directed acyclic graph of task dependencies.

    Internally the graph keeps two adjacency maps: ``_deps`` maps a node to the
    nodes it depends on (its predecessors) and ``_dependents`` maps a node to
    the nodes that depend on it (its successors). Both are kept in sync by
    :meth:`add_edge`. Insertion order is preserved in every list so traversals
    are deterministic.
    """

    def __init__(self):
        self._nodes = []
        self._node_set = set()
        self._deps = {}
        self._dependents = {}

    # -- construction -----------------------------------------------------

    def add_task(self, task_id):
        """Add an isolated node. Idempotent for an already-present node."""

        if task_id in self._node_set:
            return
        self._node_set.add(task_id)
        self._nodes.append(task_id)
        self._deps[task_id] = []
        self._dependents[task_id] = []

    def add_edge(self, dependency, dependent):
        """Record that ``dependent`` depends on ``dependency``.

        Both endpoints are created on demand. Duplicate edges are ignored so
        the adjacency lists never contain repeats. A self-edge is rejected
        immediately because it is a trivial cycle.
        """

        if dependency == dependent:
            raise GraphError(
                "task {!r} cannot depend on itself".format(dependency)
            )
        self.add_task(dependency)
        self.add_task(dependent)
        if dependency not in self._deps[dependent]:
            self._deps[dependent].append(dependency)
        if dependent not in self._dependents[dependency]:
            self._dependents[dependency].append(dependent)

    @classmethod
    def from_pipeline(cls, pipeline):
        """Build a graph from a :class:`~taskflow.model.Pipeline`.

        Every task becomes a node, and every declared dependency becomes an
        edge. A dependency that names a task not present in the pipeline is a
        configuration error surfaced as a :class:`GraphError`.
        """

        dag = cls()
        for task in pipeline.tasks():
            dag.add_task(task.id)
        for task in pipeline.tasks():
            for dep in task.deps:
                if not pipeline.has(dep):
                    raise GraphError(
                        "task {!r} depends on unknown task {!r}".format(
                            task.id, dep
                        )
                    )
                dag.add_edge(dep, task.id)
        return dag

    # -- basic queries ----------------------------------------------------

    def nodes(self):
        """Return all node identifiers in insertion order."""

        return list(self._nodes)

    def __len__(self):
        return len(self._nodes)

    def __contains__(self, task_id):
        return task_id in self._node_set

    def dependencies(self, task_id):
        """Return the direct dependencies (predecessors) of ``task_id``."""

        self._require(task_id)
        return list(self._deps[task_id])

    def dependents(self, task_id):
        """Return the direct dependents (successors) of ``task_id``."""

        self._require(task_id)
        return list(self._dependents[task_id])

    def roots(self):
        """Return nodes with no dependencies, in insertion order."""

        return [n for n in self._nodes if not self._deps[n]]

    def leaves(self):
        """Return nodes with no dependents, in insertion order."""

        return [n for n in self._nodes if not self._dependents[n]]

    def in_degree(self, task_id):
        """Return the number of direct dependencies of ``task_id``."""

        self._require(task_id)
        return len(self._deps[task_id])

    def out_degree(self, task_id):
        """Return the number of direct dependents of ``task_id``."""

        self._require(task_id)
        return len(self._dependents[task_id])

    # -- transitive queries ----------------------------------------------

    def transitive_dependents(self, task_id):
        """Return every node reachable downstream of ``task_id``.

        The traversal is a breadth-first walk over the ``_dependents`` map, so
        the returned list is ordered by distance from ``task_id`` and, within a
        distance, by insertion order. ``task_id`` itself is never included.
        This is exactly the set of tasks that must be skipped when ``task_id``
        fails permanently.
        """

        self._require(task_id)
        seen = set()
        ordered = []
        frontier = list(self._dependents[task_id])
        while frontier:
            node = frontier.pop(0)
            if node in seen:
                continue
            seen.add(node)
            ordered.append(node)
            for nxt in self._dependents[node]:
                if nxt not in seen:
                    frontier.append(nxt)
        return ordered

    def transitive_dependencies(self, task_id):
        """Return every node reachable upstream of ``task_id`` (its ancestors)."""

        self._require(task_id)
        seen = set()
        ordered = []
        frontier = list(self._deps[task_id])
        while frontier:
            node = frontier.pop(0)
            if node in seen:
                continue
            seen.add(node)
            ordered.append(node)
            for nxt in self._deps[node]:
                if nxt not in seen:
                    frontier.append(nxt)
        return ordered

    # -- ordering ---------------------------------------------------------

    def topological_levels(self):
        """Return the graph as an ordered list of parallel "levels".

        Level 0 contains the roots; level ``k`` contains every node whose
        dependencies are all satisfied by levels ``< k`` and that is not itself
        placeable earlier. This is a deterministic Kahn's-algorithm layering:
        nodes are emitted in insertion order within each level. Raises
        :class:`GraphError` if the graph contains a cycle (some nodes would
        never become placeable).
        """

        indegree = {n: len(self._deps[n]) for n in self._nodes}
        placed = set()
        levels = []
        remaining = set(self._nodes)

        while remaining:
            current = [
                n for n in self._nodes if n in remaining and indegree[n] == 0
            ]
            if not current:
                raise GraphError(
                    "cycle detected; cannot compute topological levels"
                )
            levels.append(current)
            for node in current:
                placed.add(node)
                remaining.discard(node)
                for dependent in self._dependents[node]:
                    indegree[dependent] -= 1
        return levels

    def topological_order(self):
        """Return a single flat topological ordering of all nodes."""

        order = []
        for level in self.topological_levels():
            order.extend(level)
        return order

    # -- cycle detection --------------------------------------------------

    def detect_cycle(self):
        """Return a list of nodes forming a cycle, or ``[]`` if acyclic.

        Uses an iterative depth-first search with a three-colour marking
        (white/grey/black) so it works on large graphs without recursion
        limits. When a back-edge to a grey node is found, the current DFS stack
        is sliced to return the participating nodes in order.
        """

        WHITE, GREY, BLACK = 0, 1, 2
        colour = {n: WHITE for n in self._nodes}

        for start in self._nodes:
            if colour[start] != WHITE:
                continue
            # Each stack frame: (node, iterator over its dependents).
            stack = [(start, iter(self._dependents[start]))]
            path = [start]
            colour[start] = GREY
            while stack:
                node, it = stack[-1]
                advanced = False
                for nxt in it:
                    if colour[nxt] == GREY:
                        idx = path.index(nxt)
                        return path[idx:] + [nxt]
                    if colour[nxt] == WHITE:
                        colour[nxt] = GREY
                        stack.append((nxt, iter(self._dependents[nxt])))
                        path.append(nxt)
                        advanced = True
                        break
                if not advanced:
                    colour[node] = BLACK
                    stack.pop()
                    path.pop()
        return []

    def has_cycle(self):
        """Return ``True`` if the graph contains at least one cycle."""

        return bool(self.detect_cycle())

    def assert_acyclic(self):
        """Raise :class:`GraphError` naming the cycle if one exists."""

        cycle = self.detect_cycle()
        if cycle:
            raise GraphError(
                "dependency cycle detected: {}".format(" -> ".join(cycle))
            )

    # -- reachability -----------------------------------------------------

    def is_reachable(self, source, target):
        """Return ``True`` if ``target`` lies downstream of ``source``.

        A node is not considered to reach itself unless a genuine directed
        path returns to it (which, in an acyclic graph, never happens). The
        check is a breadth-first walk over the dependents map and stops as soon
        as ``target`` is found.
        """

        self._require(source)
        self._require(target)
        seen = set()
        frontier = list(self._dependents[source])
        while frontier:
            node = frontier.pop(0)
            if node == target:
                return True
            if node in seen:
                continue
            seen.add(node)
            frontier.extend(self._dependents[node])
        return False

    def ancestors(self, task_id):
        """Return the set of nodes ``task_id`` transitively depends on."""

        return set(self.transitive_dependencies(task_id))

    def descendants(self, task_id):
        """Return the set of nodes that transitively depend on ``task_id``."""

        return set(self.transitive_dependents(task_id))

    def is_independent(self, a, b):
        """Return ``True`` if neither of ``a`` and ``b`` can reach the other.

        Two independent nodes may safely run in parallel: no dependency path
        connects them in either direction.
        """

        return not (self.is_reachable(a, b) or self.is_reachable(b, a))

    # -- shape metrics ----------------------------------------------------

    def depth(self):
        """Return the number of topological levels (the graph's critical depth).

        An empty graph has depth 0; a graph of isolated nodes has depth 1.
        """

        if not self._nodes:
            return 0
        return len(self.topological_levels())

    def width(self):
        """Return the size of the largest topological level (max parallelism)."""

        levels = self.topological_levels() if self._nodes else []
        return max((len(level) for level in levels), default=0)

    def level_of(self, task_id):
        """Return the zero-based topological level ``task_id`` sits in."""

        self._require(task_id)
        for index, level in enumerate(self.topological_levels()):
            if task_id in level:
                return index
        raise GraphError("unreachable: node not placed in any level")

    def longest_path_length(self):
        """Return the length (in edges) of the longest dependency chain.

        This is the critical-path length: the number of edges on the longest
        root-to-leaf path. A single node has length 0. Computed by dynamic
        programming over a topological order, so it is linear in the graph size
        and raises on a cyclic graph.
        """

        order = self.topological_order()
        longest = {node: 0 for node in self._nodes}
        best = 0
        for node in order:
            for dependent in self._dependents[node]:
                candidate = longest[node] + 1
                if candidate > longest[dependent]:
                    longest[dependent] = candidate
                    if candidate > best:
                        best = candidate
        return best

    def edges(self):
        """Return every ``(dependency, dependent)`` edge in a stable order."""

        pairs = []
        for node in self._nodes:
            for dependent in self._dependents[node]:
                pairs.append((node, dependent))
        return pairs

    def edge_count(self):
        """Return the total number of directed edges in the graph."""

        return sum(len(v) for v in self._dependents.values())

    def reverse(self):
        """Return a new :class:`Dag` with every edge direction flipped.

        The reversed graph has the same nodes; a dependency becomes a dependent
        and vice versa. Useful for running downstream analyses (such as
        ancestor queries) as if they were dependent queries.
        """

        flipped = Dag()
        for node in self._nodes:
            flipped.add_task(node)
        for dependency, dependent in self.edges():
            flipped.add_edge(dependent, dependency)
        return flipped

    def subgraph(self, task_ids):
        """Return the induced subgraph over ``task_ids``.

        Only edges whose *both* endpoints are in ``task_ids`` are carried over.
        Every requested node must exist in this graph.
        """

        wanted = list(task_ids)
        wanted_set = set(wanted)
        for node in wanted:
            self._require(node)
        sub = Dag()
        for node in self._nodes:
            if node in wanted_set:
                sub.add_task(node)
        for dependency, dependent in self.edges():
            if dependency in wanted_set and dependent in wanted_set:
                sub.add_edge(dependency, dependent)
        return sub

    def describe(self):
        """Return a compact multi-line human-readable description of the graph."""

        lines = [
            "Dag: {} nodes, {} edges, depth {}, width {}".format(
                len(self._nodes), self.edge_count(), self.depth(), self.width()
            ),
            "  roots: {}".format(", ".join(self.roots()) or "(none)"),
            "  leaves: {}".format(", ".join(self.leaves()) or "(none)"),
        ]
        return "\n".join(lines)

    # -- internals --------------------------------------------------------

    def _require(self, task_id):
        if task_id not in self._node_set:
            raise GraphError("unknown task: {!r}".format(task_id))

    def __repr__(self):
        return "Dag(nodes={}, edges={})".format(
            len(self._nodes),
            sum(len(v) for v in self._dependents.values()),
        )
"""Top-level entry point: run a pipeline described by a plain dictionary.

:func:`run_pipeline` ties the whole package together. Given a configuration
dictionary it:

1. loads and validates a :class:`~taskflow.model.Pipeline` (:mod:`taskflow.config`),
2. builds the dependency graph (:mod:`taskflow.dag`),
3. constructs the resource pools declared under ``pools`` (:mod:`taskflow.resources`),
4. wires a :class:`~taskflow.history.History` onto a fresh event bus,
5. runs the :class:`~taskflow.scheduler.Scheduler`, and
6. returns a :class:`RunReport` summarising the outcome.

The report exposes the final state of every task, the terminal-outcome sets,
and the observed run history, so a caller can assert on the result without
touching any internal object.
"""

from __future__ import annotations

from taskflow.config import load_pipeline
from taskflow.dag import Dag
from taskflow.events import EventBus
from taskflow.history import History
from taskflow.model import State
from taskflow.resources import ResourceManager
from taskflow.scheduler import Scheduler


class RunReport:
    """A read-only summary of a finished pipeline run.

    Wraps the scheduler's per-run records and the :class:`~taskflow.history.History`
    so callers get one object to query.
    """

    def __init__(self, pipeline, result, history):
        self.pipeline = pipeline
        self._result = result
        self.history = history

    @property
    def runs(self):
        """The ``{task_id: JobRun}`` mapping of every run."""

        return self._result.runs

    @property
    def ticks(self):
        """The number of virtual ticks the run consumed."""

        return self._result.ticks

    def state_of(self, task_id):
        """Return the final :class:`~taskflow.model.State` of ``task_id``."""

        return self._result.state_of(task_id)

    def attempts_of(self, task_id):
        """Return how many attempts ``task_id`` made."""

        return self._result.attempts_of(task_id)

    def states(self):
        """Return a ``{task_id: State}`` mapping of every final state."""

        return self._result.states()

    def succeeded(self):
        """Return the ids that ended in ``SUCCEEDED`` (pipeline order)."""

        return self._result.by_state(State.SUCCEEDED)

    def failed(self):
        """Return the ids that ended in ``FAILED`` (pipeline order)."""

        return self._result.by_state(State.FAILED)

    def skipped(self):
        """Return the ids that ended in ``SKIPPED`` (pipeline order)."""

        return self._result.by_state(State.SKIPPED)

    def run_order(self):
        """Return the order in which jobs first started (from history)."""

        return self.history.run_order()

    def ok(self):
        """Return ``True`` if every task succeeded."""

        return self._result.all_succeeded()

    def __repr__(self):
        return "RunReport(pipeline={!r}, ok={}, states={})".format(
            self.pipeline.name,
            self.ok(),
            {tid: str(s) for tid, s in self.states().items()},
        )


def _build_resources(config):
    """Construct a :class:`ResourceManager` from the ``pools`` config block."""

    pools = config.get("pools", {}) if isinstance(config, dict) else {}
    return ResourceManager(pools)


def run_pipeline(config, concurrency=None, max_ticks=None):
    """Load, run, and report on the pipeline described by ``config``.

    Parameters
    ----------
    config:
        The pipeline configuration dictionary (see :mod:`taskflow.config`). May
        additionally carry a top-level ``pools`` mapping of resource
        capacities and a ``concurrency`` integer.
    concurrency:
        Overrides the ``concurrency`` value in ``config`` when given.
    max_ticks:
        Overrides the scheduler's virtual-tick ceiling when given.
    """

    pipeline = load_pipeline(config)
    dag = Dag.from_pipeline(pipeline)

    resources = _build_resources(config)
    if concurrency is None and isinstance(config, dict):
        concurrency = config.get("concurrency")

    bus = EventBus()
    history = History(bus)

    scheduler_kwargs = {
        "dag": dag,
        "resources": resources,
        "concurrency": concurrency,
        "bus": bus,
    }
    if max_ticks is not None:
        scheduler_kwargs["max_ticks"] = max_ticks

    scheduler = Scheduler(pipeline, **scheduler_kwargs)
    result = scheduler.run()

    return RunReport(pipeline, result, history)
"""A small synchronous publish/subscribe event bus.

The scheduler narrates everything it does as a stream of :class:`~taskflow.model.Event`
objects -- jobs starting, succeeding, failing, being skipped, resources being
acquired and released. Observers (most importantly :class:`taskflow.history.History`)
subscribe to those events and build up whatever view they need.

Two kinds of subscription are supported:

* **Exact** -- :meth:`EventBus.subscribe` matches one topic string exactly.
* **Prefix** -- :meth:`EventBus.subscribe_prefix` matches a whole dotted
  subtree. Subscribing to the prefix ``"job.term"`` receives ``"job.term"``
  itself and every ``"job.term.<something>"`` such as ``"job.term.failed"`` and
  ``"job.term.skipped"``, but not the unrelated ``"job.started"``.

Delivery is synchronous, in-process, and ordered: every published event gets a
monotonically increasing sequence number, and handlers for a topic fire in the
order they subscribed. There are no threads and no real time.
"""

from __future__ import annotations

from taskflow.model import Event


def _prefix_matches(prefix, topic):
    """Return ``True`` if ``topic`` lies in the dotted subtree of ``prefix``.

    A topic matches a prefix when it equals the prefix exactly or when it is a
    dotted descendant of it. The trailing dot is required so that the prefix
    ``"job"`` matches ``"job.started"`` but not an unrelated ``"jobless"``.
    """

    return topic == prefix or prefix.startswith(topic + ".")


class Subscription:
    """A handle returned by ``subscribe`` that can later cancel delivery."""

    __slots__ = ("bus", "kind", "key", "handler", "active")

    def __init__(self, bus, kind, key, handler):
        self.bus = bus
        self.kind = kind  # "exact" or "prefix"
        self.key = key
        self.handler = handler
        self.active = True

    def cancel(self):
        """Stop delivering events to this subscription. Idempotent."""

        if self.active:
            self.bus._remove(self)
            self.active = False

    def __repr__(self):
        return "Subscription(kind={!r}, key={!r}, active={})".format(
            self.kind, self.key, self.active
        )


class EventBus:
    """A synchronous, deterministic publish/subscribe bus.

    Exact subscribers are stored per topic; prefix subscribers are stored in a
    flat, insertion-ordered list and consulted on every publish. Each publish
    stamps the event with the next sequence number and the supplied virtual
    time, then delivers it -- first to the exact subscribers of its topic, then
    to every matching prefix subscriber -- in subscription order.
    """

    def __init__(self):
        self._exact = {}
        self._prefix = []
        self._seq = 0
        self._published = []

    # -- subscription -----------------------------------------------------

    def subscribe(self, topic, handler):
        """Register ``handler`` for events published on exactly ``topic``.

        Returns a :class:`Subscription`. The same handler may subscribe to
        several topics; each call yields its own cancellable handle.
        """

        sub = Subscription(self, "exact", topic, handler)
        self._exact.setdefault(topic, []).append(sub)
        return sub

    def subscribe_prefix(self, prefix, handler):
        """Register ``handler`` for every event whose topic is under ``prefix``.

        Returns a :class:`Subscription`. Prefix subscribers see the whole
        dotted subtree rooted at ``prefix`` (see :func:`_prefix_matches`).
        """

        sub = Subscription(self, "prefix", prefix, handler)
        self._prefix.append(sub)
        return sub

    def _remove(self, sub):
        """Detach a subscription (called by :meth:`Subscription.cancel`)."""

        if sub.kind == "exact":
            bucket = self._exact.get(sub.key)
            if bucket and sub in bucket:
                bucket.remove(sub)
                if not bucket:
                    del self._exact[sub.key]
        else:
            if sub in self._prefix:
                self._prefix.remove(sub)

    # -- publishing -------------------------------------------------------

    def publish(self, topic, payload=None, at=0):
        """Publish an event on ``topic`` and deliver it synchronously.

        A fresh :class:`~taskflow.model.Event` is created, stamped with the
        next sequence number and the virtual time ``at``, appended to the bus's
        own record, and handed to every matching handler. Returns the number of
        handlers the event was delivered to.
        """

        event = Event(topic=topic, payload=payload, seq=self._seq, at=at)
        self._seq += 1
        self._published.append(event)

        delivered = 0
        # Exact subscribers of this precise topic, in subscription order.
        for sub in list(self._exact.get(topic, [])):
            if sub.active:
                sub.handler(event)
                delivered += 1
        # Prefix subscribers whose subtree contains this topic.
        for sub in list(self._prefix):
            if sub.active and _prefix_matches(sub.key, topic):
                sub.handler(event)
                delivered += 1
        return delivered

    # -- introspection ----------------------------------------------------

    def history(self):
        """Return every event ever published, in publication order."""

        return list(self._published)

    def topics(self):
        """Return the set of distinct topics that have been published."""

        return {event.topic for event in self._published}

    def subscriber_count(self, topic=None):
        """Return how many handlers would receive an event on ``topic``.

        With ``topic=None`` return the total number of live subscriptions
        (exact plus prefix).
        """

        if topic is None:
            exact = sum(len(bucket) for bucket in self._exact.values())
            return exact + len(self._prefix)
        count = len(self._exact.get(topic, []))
        count += sum(1 for s in self._prefix if _prefix_matches(s.key, topic))
        return count

    def __repr__(self):
        return "EventBus(published={}, exact_topics={}, prefix_subs={})".format(
            len(self._published), len(self._exact), len(self._prefix)
        )
